render:
const { root, params, progress, time, width, height } = ctx;
const canvas = root.querySelector('#yt-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');
const btnText = params.button_text || "SUSCRÍBETE";
const targetCount = params.target_count || 10000000;
const startCount = params.start_count || 0;
const scale = (params.card_scale || 100) / 100;
const textColor = params.text_color || "#FFFFFF";
const btnBgColor = params.btn_bg_color || "#CC0000";
const btnTextColor = params.btn_text_color || "#FFFFFF";
const bgColor = params.bg_color || "#0F0F0F";
const accelType = params.acceleration || "Exponencial Rápida";
const useBlur = (params.blur_effect || "Sí") === "Sí";

// Limpiar fondo
c.fillStyle = bgColor;
c.fillRect(0, 0, width, height);

// Cálculo de progreso no lineal (aceleración progresiva)
let rawProgress = Math.min(Math.max(progress, 0), 1);
let easeProgress = rawProgress;
let speedFactor = 0;

if (accelType === "Exponencial Rápida") {
  easeProgress = Math.pow(rawProgress, 3);
  speedFactor = 3 * Math.pow(rawProgress, 2);
} else if (accelType === "Suave") {
  easeProgress = Math.pow(rawProgress, 2);
  speedFactor = 2 * rawProgress;
} else {
  easeProgress = rawProgress;
  speedFactor = 1;
}

const currentNum = Math.floor(startCount + (targetCount - startCount) * easeProgress);

// Formatear número con separadores de miles
const formattedNum = currentNum.toLocaleString('en-US');

c.save();
const cx = width / 2;
const cy = height / 2;

// Dibujar Tarjeta/Contenedor estilo YouTube
const cardWidth = 520 * scale;
const cardHeight = 210 * scale;
const cardRadius = 16 * scale;

c.fillStyle = "rgba(255, 255, 255, 0.05)";
c.beginPath();
if (c.roundRect) {
  c.roundRect(cx - cardWidth / 2, cy - cardHeight / 2, cardWidth, cardHeight, cardRadius);
} else {
  c.rect(cx - cardWidth / 2, cy - cardHeight / 2, cardWidth, cardHeight);
}
c.fill();
c.strokeStyle = "rgba(255, 255, 255, 0.12)";
c.lineWidth = 1.5 * scale;
c.stroke();

// Etiqueta superior
c.font = `600 ${14 * scale}px system-ui, -apple-system, sans-serif`;
c.fillStyle = textColor;
c.globalAlpha = 0.6;
c.textAlign = "center";
c.fillText("SUSCRIPTORES", cx, cy - cardHeight / 2 + 35 * scale);
c.globalAlpha = 1.0;

// Calcular desfase de velocidad para el desenfoque vertical
const blurAmount = useBlur ? Math.min(14, speedFactor * 9) : 0;

c.save();
c.textAlign = "center";
c.textBaseline = "middle";
c.font = `700 ${48 * scale}px system-ui, -apple-system, sans-serif`;

if (blurAmount > 0.5) {
  // Renderizado multi-pass con atenuación alpha para simular Motion Blur
  const passes = 5;
  for (let i = -passes; i <= passes; i++) {
    const offsetY = (i / passes) * blurAmount * scale;
    const alpha = (1 - Math.abs(i) / (passes + 1)) * 0.25;
    c.fillStyle = textColor;
    c.globalAlpha = alpha;
    c.fillText(formattedNum, cx, cy - 8 * scale + offsetY);
  }
} else {
  c.fillStyle = textColor;
  c.fillText(formattedNum, cx, cy - 8 * scale);
}
c.restore();

// Dibujar Botón
const btnWidth = 190 * scale;
const btnHeight = 44 * scale;
const btnX = cx - btnWidth / 2;
const btnY = cy + cardHeight / 2 - 58 * scale;
const btnRadius = 22 * scale;

c.fillStyle = btnBgColor;
c.beginPath();
if (c.roundRect) {
  c.roundRect(btnX, btnY, btnWidth, btnHeight, btnRadius);
} else {
  c.rect(btnX, btnY, btnWidth, btnHeight);
}
c.fill();

// Texto del botón
c.font = `700 ${15 * scale}px system-ui, -apple-system, sans-serif`;
c.fillStyle = btnTextColor;
c.textAlign = "center";
c.textBaseline = "middle";
c.fillText(btnText, cx, btnY + btnHeight / 2);

c.restore();
